package com.protectionaura;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(ProjectHaloConfig.GROUP)
public interface ProjectHaloConfig extends Config
{
	String GROUP = "projecthalo";

	@ConfigSection(
		name = "General",
		description = "Core Project Halo settings",
		position = 0
	)
	String generalSection = "generalSection";

	@ConfigSection(
		name = "Colors",
		description = "Aura colors for each protection prayer",
		position = 1
	)
	String colorSection = "colorSection";

	@ConfigItem(
		keyName = "enabled",
		name = "Enable aura",
		description = "Turns Project Halo rendering on or off without disabling the plugin itself",
		position = 0,
		section = generalSection
	)
	default boolean enabled()
	{
		return true;
	}

	@Range(min = 1, max = 12)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "auraThickness",
		name = "Aura thickness",
		description = "Outline thickness in pixels",
		position = 1,
		section = generalSection
	)
	default int auraThickness()
	{
		return 4;
	}

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "auraOpacity",
		name = "Aura opacity",
		description = "Opacity percentage applied to all aura colors",
		position = 2,
		section = generalSection
	)
	default int auraOpacity()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "meleeColor",
		name = "Protect from Melee color",
		description = "Aura color used when Protect from Melee is active",
		position = 3,
		section = colorSection
	)
	default Color meleeColor()
	{
		return new Color(220, 48, 48);
	}

	@ConfigItem(
		keyName = "rangeColor",
		name = "Protect from Missiles color",
		description = "Aura color used when Protect from Missiles is active",
		position = 4,
		section = colorSection
	)
	default Color rangeColor()
	{
		return new Color(56, 168, 84);
	}

	@ConfigItem(
		keyName = "magicColor",
		name = "Protect from Magic color",
		description = "Aura color used when Protect from Magic is active",
		position = 5,
		section = colorSection
	)
	default Color magicColor()
	{
		return new Color(64, 118, 232);
	}
}

package com.protectionaura;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class ProjectHaloOverlay extends Overlay
{
	private final Client client;
	private final ProjectHaloPlugin plugin;
	private final ProjectHaloConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private ProjectHaloOverlay(
		Client client,
		ProjectHaloPlugin plugin,
		ProjectHaloConfig config,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enabled() || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		renderPlayer(client.getLocalPlayer());
		return null;
	}

	private void renderPlayer(Player player)
	{
		final Color auraColor = plugin.getAuraColor(player);
		if (auraColor == null)
		{
			return;
		}

		modelOutlineRenderer.drawOutline(
			player,
			config.auraThickness(),
			auraColor,
			plugin.getAuraFeather());
	}
}

package com.protectionaura;

import com.google.inject.Provides;
import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Project Halo",
	description = "Visual-only prayer aura for visible protection prayers",
	tags = {"prayer", "outline", "aura", "overlay", "visual"}
)
public class ProjectHaloPlugin extends Plugin
{
	private ProtectionPrayer activeLocalPrayer = ProtectionPrayer.NONE;
	private Color meleeAuraColor;
	private Color rangeAuraColor;
	private Color magicAuraColor;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ProjectHaloOverlay overlay;

	@Inject
	private ProjectHaloConfig config;

	@Override
	protected void startUp()
	{
		refreshCachedColors();
		refreshLocalProtectionPrayer();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		activeLocalPrayer = ProtectionPrayer.NONE;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			refreshLocalProtectionPrayer();
			return;
		}

		activeLocalPrayer = ProtectionPrayer.NONE;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		final int varbitId = event.getVarbitId();
		// A varplayer update can change backing prayer bits without naming one varbit.
		if (varbitId == -1
			|| varbitId == Prayer.PROTECT_FROM_MELEE.getVarbit()
			|| varbitId == Prayer.PROTECT_FROM_MISSILES.getVarbit()
			|| varbitId == Prayer.PROTECT_FROM_MAGIC.getVarbit())
		{
			refreshLocalProtectionPrayer();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ProjectHaloConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		refreshCachedColors();
	}

	Color getAuraColor(Player player)
	{
		final ProtectionPrayer protectionPrayer = resolveProtectionPrayer(player);
		switch (protectionPrayer)
		{
			case MELEE:
				return meleeAuraColor;
			case MISSILES:
				return rangeAuraColor;
			case MAGIC:
				return magicAuraColor;
			case NONE:
			default:
				return null;
		}
	}

	int getAuraFeather()
	{
		return Math.max(2, Math.min(8, config.auraThickness() + 1));
	}

	private void refreshLocalProtectionPrayer()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			activeLocalPrayer = ProtectionPrayer.NONE;
			return;
		}

		if (isPrayerActive(Prayer.PROTECT_FROM_MELEE))
		{
			activeLocalPrayer = ProtectionPrayer.MELEE;
		}
		else if (isPrayerActive(Prayer.PROTECT_FROM_MISSILES))
		{
			activeLocalPrayer = ProtectionPrayer.MISSILES;
		}
		else if (isPrayerActive(Prayer.PROTECT_FROM_MAGIC))
		{
			activeLocalPrayer = ProtectionPrayer.MAGIC;
		}
		else
		{
			activeLocalPrayer = ProtectionPrayer.NONE;
		}
	}

	private boolean isPrayerActive(Prayer prayer)
	{
		return client.getVarbitValue(prayer.getVarbit()) == 1;
	}

	private ProtectionPrayer resolveProtectionPrayer(Player player)
	{
		if (player == null || player.isDead() || player.getModel() == null)
		{
			return ProtectionPrayer.NONE;
		}

		final Player localPlayer = client.getLocalPlayer();
		if (player == localPlayer)
		{
			return activeLocalPrayer;
		}

		return ProtectionPrayer.NONE;
	}

	private void refreshCachedColors()
	{
		meleeAuraColor = withOpacity(config.meleeColor());
		rangeAuraColor = withOpacity(config.rangeColor());
		magicAuraColor = withOpacity(config.magicColor());
	}

	private Color withOpacity(Color baseColor)
	{
		final int opacityPercent = Math.max(0, Math.min(100, config.auraOpacity()));
		final int alpha = Math.round(opacityPercent * 255.0f / 100.0f);
		return new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), alpha);
	}

	@Provides
	ProjectHaloConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ProjectHaloConfig.class);
	}

	private enum ProtectionPrayer
	{
		NONE,
		MELEE,
		MISSILES,
		MAGIC
	}
}

package com.protectionaura;

import java.awt.Color;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.events.ConfigChanged;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/** Tests plugin state logic without starting a client or logging into an account. */
public class ProjectHaloBehaviorTest
{
	private ProjectHaloPlugin plugin;
	private Prayer prayer;
	private GameState state = GameState.LOGGED_IN;
	private boolean dead;
	private boolean modelAvailable = true;
	private Player local;
	private Player other;
	private final ProjectHaloConfig config = new ProjectHaloConfig() {};

	@Before
	public void setUp() throws Exception
	{
		Model model = proxy(Model.class, (object, method, args) -> defaultValue(method.getReturnType()));
		local = proxy(Player.class, (object, method, args) -> {
			if (method.getName().equals("getModel")) return modelAvailable ? model : null;
			if (method.getName().equals("isDead")) return dead;
			return defaultValue(method.getReturnType());
		});
		other = proxy(Player.class, (object, method, args) -> {
			if (method.getName().equals("getModel")) return model;
			return defaultValue(method.getReturnType());
		});
		Client client = proxy(Client.class, (object, method, args) -> {
			switch (method.getName())
			{
				case "getGameState": return state;
				case "getLocalPlayer": return local;
				case "getVarbitValue": return prayer != null && ((Integer) args[0]) == prayer.getVarbit() ? 1 : 0;
				default: return defaultValue(method.getReturnType());
			}
		});
		plugin = new ProjectHaloPlugin();
		inject("client", client);
		inject("config", config);
		ConfigChanged changed = new ConfigChanged();
		changed.setGroup(ProjectHaloConfig.GROUP);
		plugin.onConfigChanged(changed);
	}

	@Test
	public void protectionPrayersUseConfiguredColorsAndOpacity()
	{
		assertPrayer(Prayer.PROTECT_FROM_MELEE, config.meleeColor());
		assertPrayer(Prayer.PROTECT_FROM_MISSILES, config.rangeColor());
		assertPrayer(Prayer.PROTECT_FROM_MAGIC, config.magicColor());
	}

	@Test
	public void disablingPrayerRemovesAura()
	{
		prayer = Prayer.PROTECT_FROM_MELEE;
		refresh();
		assertNotNull(plugin.getAuraColor(local));
		prayer = null;
		refresh();
		assertNull(plugin.getAuraColor(local));
	}

	@Test
	public void otherPlayersAndUnavailableModelsHaveNoAura()
	{
		prayer = Prayer.PROTECT_FROM_MAGIC;
		refresh();
		assertNull(plugin.getAuraColor(other));
		assertNull(plugin.getAuraColor(null));
		dead = true;
		assertNull(plugin.getAuraColor(local));
		dead = false;
		modelAvailable = false;
		assertNull(plugin.getAuraColor(local));
	}

	@Test
	public void bulkVarpUpdateRefreshesPrayer()
	{
		prayer = Prayer.PROTECT_FROM_MELEE;
		refresh();
		prayer = null;
		VarbitChanged changed = new VarbitChanged();
		changed.setVarbitId(-1);
		plugin.onVarbitChanged(changed);
		assertNull("A bulk varp change should not leave an old aura cached", plugin.getAuraColor(local));
	}

	@Test
	public void varplayerUpdateActivatesAndSwitchesPrayer()
	{
		VarbitChanged changed = new VarbitChanged();
		changed.setVarbitId(-1);
		prayer = Prayer.PROTECT_FROM_MELEE;
		plugin.onVarbitChanged(changed);
		assertEquals(config.meleeColor().getRGB() & 0xffffff, plugin.getAuraColor(local).getRGB() & 0xffffff);
		prayer = Prayer.PROTECT_FROM_MAGIC;
		plugin.onVarbitChanged(changed);
		assertEquals(config.magicColor().getRGB() & 0xffffff, plugin.getAuraColor(local).getRGB() & 0xffffff);
	}

	@Test
	public void varplayerUpdateWhileLoggedOutDoesNotCreateAura()
	{
		state = GameState.LOGIN_SCREEN;
		prayer = Prayer.PROTECT_FROM_MELEE;
		VarbitChanged changed = new VarbitChanged();
		changed.setVarbitId(-1);
		plugin.onVarbitChanged(changed);
		assertNull(plugin.getAuraColor(local));
	}

	private void assertPrayer(Prayer active, Color expected)
	{
		prayer = active;
		refresh();
		Color actual = plugin.getAuraColor(local);
		assertNotNull(actual);
		assertEquals(expected.getRGB() & 0xffffff, actual.getRGB() & 0xffffff);
		assertEquals(153, actual.getAlpha());
	}

	private void refresh()
	{
		VarbitChanged changed = new VarbitChanged();
		changed.setVarbitId(Prayer.PROTECT_FROM_MELEE.getVarbit());
		plugin.onVarbitChanged(changed);
	}

	private void inject(String name, Object value) throws Exception
	{
		Field field = ProjectHaloPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	private static <T> T proxy(Class<T> type, java.lang.reflect.InvocationHandler handler)
	{
		return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, handler));
	}

	private static Object defaultValue(Class<?> type)
	{
		if (type == boolean.class) return false;
		if (type == int.class) return 0;
		if (type == long.class) return 0L;
		if (type == float.class) return 0f;
		if (type == double.class) return 0d;
		return null;
	}
}

package com.protectionaura;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ProjectHaloPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ProjectHaloPlugin.class);
		RuneLite.main(args);
	}
}
